WITH flattened AS (SELECT id, plan, effective_from, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(discounts) x AS tier_value) SELECT id, effective_from, tier_value, CUME_DIST() OVER (PARTITION BY currency ORDER BY tier_value DESC NULLS FIRST) AS tier_value_cume_dist, STDDEV_SAMP(tier_value) OVER (PARTITION BY plan, currency) AS plan_stddev_samp_tier_value, DENSE_RANK() OVER (ORDER BY tier_value ASC NULLS FIRST) AS tier_value_dense_rank, PERCENT_RANK() OVER (PARTITION BY currency ORDER BY tier_value ASC NULLS LAST) AS tier_value_percent_rank FROM flattened WHERE currency IN ('USD', 'THB');
